contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= _value);

        bool reverted;
        uint balBefore = address(c).balance;

        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;

        assert(!reverted || balAfter == balBefore);
    }

    receive() external payable {}
}

